import requests
from lxml import html
import pandas as pd
import sqlite3

def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if webpage_url.startswith("file://"):
        with open(webpage_url[7:], 'r') as f:
            content = f.read()
    else:
        try:
            response = requests.get(webpage_url)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as e:
            raise requests.RequestException(f"Network issue accessing URL: {e}")

    tree = html.fromstring(content)
    table = tree.xpath('//table')[0] if tree.xpath('//table') else None
    if table is None:
        return 0

    rows = table.xpath('.//tr')
    data = []
    for row in rows:
        cols = row.xpath('.//td|.//th')
        if not cols:
            continue
        cols = [col.text_content().strip() for col in cols]
        data.append(cols)

    if not data:
        return 0

    df = pd.DataFrame(data[1:], columns=data[0] if data else None)

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.commit()
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

    return len(df)

