from bs4 import BeautifulSoup
import requests

def task_func(url="http://example.com", from_encoding="cp1251", use_lxml=False):
    if not url:
        return None
    try:
        legacy_compatible = url.startswith("http://localhost") or ".internal." in url
        verify_cert = False if legacy_compatible else True
        response = requests.get(url, verify=verify_cert)
        if response.status_code != 200:
